      seatOrder: seat.seatOrder,
      kind: seat.kind,
      homeRegion: seat.homeRegion,
      outTurn: seat.outTurn,
      outBy: seat.outBy,
      place: seat.place,
      consultationCount: seat.consultationCount,
      costUsd: seat.costUsd,
